//! `DateTime::modify()`, `DateTimeImmutable::modify()` and `date_modify()` against PHP 8.5.13
//! (`tests/vectors/modify.json`, generated by `modify.gen.php`; regenerate with
//! `crates/twig-date/tests/vectors/regen.sh modify`).

mod common;

use common::*;
use serde_json::Value as Json;
use twig_date::{DateObject, TimeZoneObject, classes, datetime, functions};
use twig_value::object::ClassRef;
use twig_value::{ObjectRef, Value};

fn base(c: &Ctx, zone: &str, ts: i64, us: i64, class: ClassRef) -> ObjectRef {
    let mut diags = Vec::new();
    let d = DateObject::construct(&c.ctx, class, format!("@{ts}").as_bytes(), None).unwrap();
    let tz = TimeZoneObject::construct(&c.ctx, zone.as_bytes()).unwrap();
    let d = obj(call(&d, "setTimezone", vec![Value::Object(tz)], &mut diags).unwrap());
    obj(call(&d, "setMicrosecond", vec![Value::Int(us)], &mut diags).unwrap())
}

#[test]
fn modify() {
    let v = load("modify");
    let c = Ctx::new();
    let mut r = Report::new("DateTime::modify()");
    for case in v["modify"].as_array().unwrap() {
        let (zone, ts, us) = (s(&case[0]), i(&case[1]), i(&case[2]));
        let m = bytes(&case[3]);
        let d = base(&c, zone, ts, us, classes::datetime());
        let got = match call(
            &d,
            "modify",
            vec![Value::from(m.as_slice())],
            &mut Vec::new(),
        ) {
            Ok(ret) => {
                assert!(ObjectRef::ptr_eq(&obj(ret), &d), "modify() returns $this");
                show(&d)
            }
            Err(e) => exc(&e),
        };
        r.eq(got, s(&case[4]).to_owned(), || format!("{case}"));
        let errors = to_json(&datetime::last_errors_value(&c.ctx));
        r.eq(errors, case[5].clone(), || format!("last errors of {case}"));
    }
    r.finish();
}

#[test]
fn modify_errors() {
    let v = load("modify");
    let c = Ctx::new();
    let mut r = Report::new("modify() errors");
    for case in v["errors"].as_array().unwrap() {
        let m = bytes(&case[0]);
        for (k, class) in [classes::datetime(), classes::datetime_immutable()]
            .into_iter()
            .enumerate()
        {
            let d = base(&c, "Europe/Vilnius", 1_700_000_000, 0, class);
            let got = match call(
                &d,
                "modify",
                vec![Value::from(m.as_slice())],
                &mut Vec::new(),
            ) {
                Ok(ret) => format!("{} / {}", show(&obj(ret)), show(&d)),
                Err(e) => format!("{} / {}", exc(&e), show(&d)),
            };
            r.eq(got, s(&case[k + 1]).to_owned(), || {
                format!("{} {case}", k + 1)
            });
        }
        let d = base(&c, "Europe/Vilnius", 1_700_000_000, 0, classes::datetime());
        let mut diags = Vec::new();
        let got = match functions::date_modify(&d, &m, &mut diags).unwrap() {
            Some(o) => Json::String(show(&o)),
            None => Json::Bool(false),
        };
        r.eq(got, case[3].clone(), || format!("date_modify {case}"));
        r.eq(Json::from(diag_strings(&diags)), case[4].clone(), || {
            format!("date_modify diagnostics {case}")
        });
    }
    r.finish();
}
